/**
 * Tag completion of the Source view (feature 003 User Story 8, FR-070 to FR-075; research R9).
 *
 * One completion source over `@codemirror/autocomplete`, driven by the FB2 2.1 schema table
 * `fb2Elements.json` (generated by `tools/fb2-schema-elements.py`: every element with the
 * child elements its content model allows, flattened):
 *
 *  - after `<` and a (possibly empty) name prefix: the children of the innermost open element
 *    at the cursor; every element but the root when that element is unknown or the syntax tree
 *    does not reach the cursor yet; the root alone at the document level; accepting inserts the
 *    name and nothing else, replacing only the typed prefix (never the text after the cursor);
 *  - after `</` and a prefix: the elements open at the cursor and not yet closed, innermost
 *    first (each name once); accepting inserts the complete closing tag; nothing when no
 *    element is open or the syntax tree does not reach the cursor yet;
 *  - nothing inside comments, processing instructions, CDATA sections, doctype declarations
 *    and attribute values (FR-073; attributes are out of scope, FR-076), nothing where the
 *    schema allows no child element - including the `…N bytes…` placeholder of a `<binary>`,
 *    whose content model has no elements - and nothing when the cursor does not follow a tag
 *    start, not even on demand.
 *
 * Context comes from the Lezer XML tree: the ancestors of the node at the cursor that are
 * `Element`s, except the tag being typed itself (its `OpenTag` starts at the `<` before the
 * cursor) and elements whose `CloseTag` ends before that `<`. An element whose closing tag is
 * missing (`MissingCloseTag`) or mismatched (`MismatchedCloseTag` closes nothing) therefore
 * counts as open, so a malformed document still completes what the editor finds open. The
 * parser gets a small time budget to reach the cursor; past it the context is "unknown".
 *
 * Filtering is CodeMirror's strict prefix match (case-insensitive; the schema's spelling is
 * inserted), kept synchronous while the user types a name (`validFor`). Enter and Tab accept,
 * Escape dismisses, the arrow keys move; without a list every key works as before. The hotkey
 * (`edit.completeTag`, default Ctrl+Space) is an application command, so CodeMirror's own
 * keymap is off and the Hotkeys page can rebind it.
 */

import {
  acceptCompletion,
  autocompletion,
  closeCompletion,
  completionStatus,
  moveCompletionSelection,
  pickedCompletion,
  startCompletion,
  type Completion,
  type CompletionContext,
  type CompletionResult,
} from '@codemirror/autocomplete';
import { ensureSyntaxTree } from '@codemirror/language';
import { Prec, type EditorState, type Extension } from '@codemirror/state';
import { EditorView, keymap, type KeyBinding } from '@codemirror/view';
import type { SyntaxNode } from '@lezer/common';

import type { AppStore } from '@/model/store';

import fb2ElementsJson from './fb2Elements.json';

/* ------------------------------------------------------------------------ */
/* The table                                                                */
/* ------------------------------------------------------------------------ */

export interface Fb2Elements {
  /** The document element (`FictionBook`), offered only at the document level. */
  root: string;
  /** Every element name with the sorted names of the elements it may contain. */
  elements: Record<string, { children: string[] }>;
}

/** The generated completion table (`tools/fb2-schema-elements.py`, checked by CI). */
export const FB2_ELEMENTS: Fb2Elements = fb2ElementsJson;

/** Every element but the root: what is offered when the enclosing element is unknown. */
const NON_ROOT_NAMES: readonly string[] = Object.keys(FB2_ELEMENTS.elements).filter(
  (name) => name !== FB2_ELEMENTS.root,
);

/* ------------------------------------------------------------------------ */
/* Context                                                                  */
/* ------------------------------------------------------------------------ */

export interface OpenTagContext {
  kind: 'open';
  /** Offset of the `<`. */
  from: number;
  /** The name typed so far (may be empty). */
  prefix: string;
  /** The innermost open element, or null at the document level. */
  enclosing: string | null;
  /** False when the syntax tree does not reach the cursor: the context is unknown. */
  resolved: boolean;
}

export interface CloseTagContext {
  kind: 'close';
  /** Offset of the `<` of `</`. */
  from: number;
  prefix: string;
  /** The open elements, innermost first, each name once. */
  open: string[];
}

export type TagContext = OpenTagContext | CloseTagContext;

/** `<` or `</` followed by the start of a name, right before the cursor. */
const TAG_START = /<\/?[\w.:-]*$/;
/** How far back the tag start is looked for (a name longer than this completes nothing). */
const LOOKBEHIND = 256;
/** Time the parser may spend reaching the cursor before the context counts as unknown (ms). */
const PARSE_BUDGET_MS = 50;
/** Nodes in which no completion is offered (FR-073). */
const FORBIDDEN = new Set(['Comment', 'ProcessingInst', 'Cdata', 'DoctypeDecl', 'AttributeValue']);
/** Typing or deleting within the name keeps the result and filters it synchronously. */
const NAME_CHARS = /^[\w.:-]*$/;

function tagName(state: EditorState, tag: SyntaxNode): string | null {
  const name = tag.getChild('TagName');
  return name ? state.sliceDoc(name.from, name.to) : null;
}

/** The element name without a namespace prefix (`fb:section` -> `section`). */
function localName(name: string): string {
  const colon = name.indexOf(':');
  return colon >= 0 ? name.slice(colon + 1) : name;
}

/**
 * The tag completion context at `pos`, or null when the cursor does not follow a tag start
 * or sits where no completion belongs (comment, processing instruction, CDATA, doctype,
 * attribute value).
 */
export function tagContextAt(state: EditorState, pos: number): TagContext | null {
  const line = state.doc.lineAt(pos);
  const before = state.sliceDoc(Math.max(line.from, pos - LOOKBEHIND), pos);
  const match = TAG_START.exec(before);
  if (!match) return null;
  const from = pos - match[0].length;
  const close = match[0].startsWith('</');
  const prefix = match[0].slice(close ? 2 : 1);

  const tree = ensureSyntaxTree(state, pos, PARSE_BUDGET_MS);
  // Without a tree up to the cursor the forbidden contexts (comments, CDATA...) cannot be
  // told apart: offer nothing this time; the next keystroke or Ctrl+Space asks again.
  if (!tree) return null;
  const node = tree.resolveInner(pos, -1);
  for (let cur: SyntaxNode | null = node; cur; cur = cur.parent) {
    if (FORBIDDEN.has(cur.name)) return null;
  }
  const open: string[] = [];
  for (let cur: SyntaxNode | null = node; cur; cur = cur.parent) {
    if (cur.name !== 'Element') continue;
    const openTag = cur.firstChild;
    if (!openTag || openTag.name !== 'OpenTag') continue; // self-closing: no content
    if (openTag.from === from) continue; // the tag being typed
    const last = cur.lastChild;
    if (last && last.name === 'CloseTag' && last.to <= from) continue; // closed already
    const name = tagName(state, openTag);
    if (name && !open.includes(name)) open.push(name);
  }
  if (close) return { kind: 'close', from, prefix, open };
  return { kind: 'open', from, prefix, enclosing: open[0] ?? null, resolved: true };
}

/* ------------------------------------------------------------------------ */
/* The source                                                               */
/* ------------------------------------------------------------------------ */

/** Inserts `</name>` in place of the `</` and the typed prefix. */
function applyClosingTag(view: EditorView, completion: Completion, from: number, to: number): void {
  const text = `</${completion.label}>`;
  // `from` is the start of the typed name; the `</` before it belongs to the tag.
  const start = view.state.sliceDoc(from - 2, from) === '</' ? from - 2 : from;
  view.dispatch({
    changes: { from: start, to, insert: text },
    selection: { anchor: start + text.length },
    scrollIntoView: true,
    userEvent: 'input.complete',
    annotations: pickedCompletion.of(completion),
  });
}

/** Children of `element`, or null when it is not an FB2 element. */
function childrenOf(element: string): readonly string[] | null {
  return FB2_ELEMENTS.elements[localName(element)]?.children ?? null;
}

/** The completion source: FB2 element names after `<`, closing tags after `</`. */
export function fb2Completion(context: CompletionContext): CompletionResult | null {
  const tag = tagContextAt(context.state, context.pos);
  if (!tag) return null;
  if (tag.kind === 'close') {
    if (tag.open.length === 0) return null;
    return {
      from: tag.from + 2,
      options: tag.open.map((name, index) => ({
        label: name,
        // Innermost first: the matcher scores every name alike, the boost orders them.
        boost: Math.max(-99, 99 - index),
        apply: applyClosingTag,
      })),
      validFor: NAME_CHARS,
    };
  }
  let names: readonly string[];
  if (!tag.resolved) names = NON_ROOT_NAMES;
  else if (tag.enclosing === null) names = [FB2_ELEMENTS.root];
  else names = childrenOf(tag.enclosing) ?? NON_ROOT_NAMES;
  if (names.length === 0) return null;
  return {
    from: tag.from + 1,
    // `apply` is the name: the completion inserts it and nothing else (FR-072).
    options: names.map((name) => ({ label: name, apply: name })),
    validFor: NAME_CHARS,
  };
}

/* ------------------------------------------------------------------------ */
/* The extension                                                            */
/* ------------------------------------------------------------------------ */

/**
 * The keys of an open list. Without a list every command returns false, so Enter breaks the
 * line, Tab indents and Escape reaches the bindings after this keymap as before (FR-072).
 */
const completionKeys: readonly KeyBinding[] = [
  { key: 'Escape', run: closeCompletion },
  { key: 'ArrowDown', run: moveCompletionSelection(true) },
  { key: 'ArrowUp', run: moveCompletionSelection(false) },
  { key: 'PageDown', run: moveCompletionSelection(true, 'page') },
  { key: 'PageUp', run: moveCompletionSelection(false, 'page') },
  { key: 'Enter', run: acceptCompletion },
  { key: 'Tab', run: acceptCompletion },
];

/** Test id of the completion list (`source-completion`). */
export const COMPLETION_TEST_ID = 'source-completion';

/**
 * Stamps the stable test id on the list: CodeMirror builds the tooltip itself and offers a
 * class hook (`tooltipClass`) but no attribute hook. Runs after the tooltip plugin has created
 * the element, once per list.
 */
const completionTestId = EditorView.updateListener.of((update) => {
  if (completionStatus(update.state) !== 'active') return;
  const list = update.view.dom.querySelector('.cm-tooltip-autocomplete:not([data-testid])');
  list?.setAttribute('data-testid', COMPLETION_TEST_ID);
});

/**
 * Tag completion for the Source editor (Settings > View > "Tag completion"): the FB2 source
 * replaces lang-xml's language-data completion (`override`), typing opens the list, no icons,
 * strict prefix filtering; the keymap above has precedence over the editor's keymaps. Off:
 * nothing (no completion state, so the command's `startCompletion` is a no-op).
 */
export function sourceCompletionExtension(on: boolean): Extension {
  if (!on) return [];
  return [
    autocompletion({
      override: [fb2Completion],
      activateOnTyping: true,
      icons: false,
      filterStrict: true,
      defaultKeymap: false,
      tooltipClass: () => 'mfbe-source-completion',
    }),
    Prec.high(keymap.of(completionKeys)),
    completionTestId,
  ];
}

/* ------------------------------------------------------------------------ */
/* Command support                                                          */
/* ------------------------------------------------------------------------ */

/*
 * `edit.completeTag` (app/commands.ts) opens the list of the Source editor of its store. The
 * editor controller registers how to reach its mounted view here, so the command module needs
 * no import of the editor (which imports the command module for `switchView`).
 */
const completionEditors = new WeakMap<AppStore, () => EditorView | null>();

/** Registers the Source editor of `store` (its mounted view, or null while unmounted). */
export function registerCompletionEditor(store: AppStore, view: () => EditorView | null): void {
  completionEditors.set(store, view);
}

/** Opens the suggestions for the cursor position in the Source editor of `store`. */
export function startSourceTagCompletion(store: AppStore): boolean {
  const view = completionEditors.get(store)?.();
  return view ? startCompletion(view) : false;
}
